function firstLine(text, max = 120) {
  const line = String(text || '')
    .split('\n')
    .map((l) => l.replace(/^[^\p{L}\p{N}]+|[\s:,;\-]+$/gu, '').trim())
    .find(Boolean);
  if (!line) return '';
  return line.length > max ? line.slice(0, max - 1).replace(/\s+\S*$/, '') + '…' : line;
}

